    /// <summary>
    /// ## Connect a device to a terminal
    ///
    /// Connect a device to a terminal instance. If the terminal has no device bound,
    /// this will bind the provided `device_id` and generate a fresh API key token
    /// (prefixed with `reservepay_`). If the terminal is already bound to the same
    /// `device_id`, the previous key is revoked and a new one is issued.
    ///
    /// If the terminal is bound to a different device, an `ALREADY_CONNECTED` error
    /// is returned.
    ///
    /// If the terminal is disabled, `NOT_ENABLED` is returned.
    ///
    /// If the terminal has no installation linked, `NOT_CONFIGURED` is returned.
    /// </summary>
    /// <exception cref="global::WebFunction.Exceptions.BadRequestException">code "ALREADY_CONNECTED" - The terminal is connected to another device.</exception>
    /// <exception cref="global::WebFunction.Exceptions.BadRequestException">code "INVALID_CHALLENGE" - The challenge is missing or does not match the terminal's current challenge.</exception>
    /// <exception cref="global::WebFunction.Exceptions.BadRequestException">code "NOT_FOUND" - Merchant or terminal could not be found.</exception>
    /// <exception cref="global::WebFunction.Exceptions.BadRequestException">code "NOT_ENABLED" - The terminal exists but is disabled; enable it before connecting a device.</exception>
    /// <exception cref="global::WebFunction.Exceptions.BadRequestException">code "NOT_CONFIGURED" - The terminal has no installation linked; assign an installation first.</exception>
    /// <exception cref="global::WebFunction.Exceptions.UnexpectedStatusCodeException">if the server responds with a non-200/400 status</exception>
    /// <exception cref="global::WebFunction.Exceptions.JsonParseException">if the response body isn't valid JSON</exception>
    public async Task<string> ConnectDevice(ConnectDeviceArgs args)
    {
        var argsMap = ToArgsMap(args);
        var result = await CallAsync("connect-device", argsMap).ConfigureAwait(false);
        return DecodeResult<string>(result);
    }

    /// <summary>
    /// ## Connect a device with a temporary challenge
    ///
    /// Connect a device to the terminal that owns the given 8-digit temporary challenge.
    /// The code must be unexpired. On success the device is bound, the temporary challenge
    /// is cleared, and the response holds the merchant ID, the terminal ID and a fresh API
    /// key token (prefixed with `reservepay_`).
    ///
    /// If the terminal is already bound to a different device, `ALREADY_CONNECTED` is returned.
    /// If it is bound to the same device, the previous key is revoked and a new one is issued.
    ///
    /// If the terminal is disabled, `NOT_ENABLED` is returned.
    ///
    /// If the terminal has no installation linked, `NOT_CONFIGURED` is returned.
    /// </summary>
    /// <exception cref="global::WebFunction.Exceptions.BadRequestException">code "ALREADY_CONNECTED" - The terminal is connected to another device.</exception>
    /// <exception cref="global::WebFunction.Exceptions.BadRequestException">code "INVALID_CHALLENGE" - The code is unknown or has expired.</exception>
    /// <exception cref="global::WebFunction.Exceptions.BadRequestException">code "NOT_ENABLED" - The terminal exists but is disabled; enable it before connecting a device.</exception>
    /// <exception cref="global::WebFunction.Exceptions.BadRequestException">code "NOT_CONFIGURED" - The terminal has no installation linked; assign an installation first.</exception>
    /// <exception cref="global::WebFunction.Exceptions.UnexpectedStatusCodeException">if the server responds with a non-200/400 status</exception>
    /// <exception cref="global::WebFunction.Exceptions.JsonParseException">if the response body isn't valid JSON</exception>
    public async Task<ConnectDeviceByCodeResult> ConnectDeviceByCode(ConnectDeviceByCodeArgs args)
    {
        var argsMap = ToArgsMap(args);
        var result = await CallAsync("connect-device-by-code", argsMap).ConfigureAwait(false);
        return DecodeResult<ConnectDeviceByCodeResult>(result);
    }

